@lru_cache(maxsize=1)
def assinatura_cabecalho_png():
    """PNG RGBA empacotado no módulo para suportar compilação PyInstaller."""
    return zlib.decompress(base64.b85decode(_B85_COMPRESSED_PNG.encode('ascii')))
